47	/** Constrói uma chain encadeável genérica que resolve para `result`. */
48	function makeChain(
49	  result: unknown,
50	  overrides: Record<string, unknown> = {},
51	): Record<string, unknown> {
52	  const chain: Record<string, unknown> = {
53	    select: vi.fn().mockReturnThis(),
54	    insert: vi.fn().mockReturnThis(),
55	    update: vi.fn().mockReturnThis(),
56	    delete: vi.fn().mockReturnThis(),
57	    upsert: vi.fn().mockReturnThis(),
58	    eq: vi.fn().mockReturnThis(),
59	    neq: vi.fn().mockReturnThis(),
60	    order: vi.fn().mockReturnThis(),
61	    limit: vi.fn().mockReturnThis(),
62	    head: vi.fn().mockReturnThis(),
63	    maybeSingle: vi.fn().mockResolvedValue(result),
64	    single: vi.fn().mockResolvedValue(result),
65	    then: (resolve: (v: unknown) => unknown) =>
66	      Promise.resolve(result).then(resolve),
67	    ...overrides,
68	  };
69	  return chain;
70	}
